        for ic in row:
            gc=gws[ic.coordinate].value
            if ic.value is None and gc is not None:
                if isinstance(gc,str) and gc.startswith('='):
                    formula_diffs.append((name,ic.coordinate,gc))
                else:
                    data_diffs.append((name,ic.coordinate,gc))
